\title{\vspace*{-2.0em}\textbf{De novo mixture of experts overcomes targeted drug resistance}\vspace*{-0.5em}}

\author{
    \normalsize
    \textbf{V.~C.~Premchand~Yadav}$^{1}$,\quad
    \textbf{K.~SriHarsha~Vardhan}$^{1}$,\quad
    \textbf{Edupulapati~Sai~Praneeth}$^{1}$,\\[0.2em]
