\begin{document}

\begin{singlespace}
\maketitle

\vspace*{-1.5em}
\begin{center}
\footnotesize
$^{1}$School of Computer Science and Engineering (SCOPE), VIT-AP University, Amaravati, Andhra Pradesh 522237, India.\\
